"""Tests for file ownership: the mark, placing a conversion beside hand-written files, cleanup."""

from __future__ import annotations

from pathlib import Path

import pytest

from tools.convert import ownership
from tools.convert.tests.helpers import OURS, write


def test_mark(tmp_path: Path) -> None:
    """Ours is `@generated` and rules_cc_autoconf, both: a project's own generated files are not."""
    write(tmp_path / "ours.bzl", OURS + "x = 1\n")
    write(tmp_path / "theirs.c", "/* @generated by protoc */\nint x;\n")
    write(tmp_path / "plain.bzl", "x = 1\n")
    assert ownership.is_owned(tmp_path / "ours.bzl")
    assert not ownership.is_owned(tmp_path / "theirs.c")
    assert not ownership.is_owned(tmp_path / "plain.bzl")
    assert not ownership.is_owned(tmp_path / "missing")
    marked = ownership.marked("#undef X\n", ".in", "autoheader's template")
    assert marked == ("/* @generated: autoheader's template, by rules_cc_autoconf convert; do not edit. */\n#undef X\n")
    lines = ownership.marked("#!/bin/sh\necho\n", ".sh", "w").splitlines()
    assert lines[0] == "#!/bin/sh"
    assert lines[1].startswith("# @generated: w, by rules_cc_autoconf")
    assert ownership.marked("data", ".bin", "w") == "data"


def test_sync(tmp_path: Path) -> None:
    """Generated files are written, hand-written ones kept, an identical unmarked one rewritten,
    the converter's stale files removed with the directory that empties; a hand-written file in
    the way that differs stops the run before anything is written."""
    staging, dest = tmp_path / "staging", tmp_path / "dest"
    write(staging / "BUILD.bazel", OURS + "a = 1\n")
    write(staging / "lib/BUILD.bazel", OURS + "b = 1\n")
    write(staging / "same.txt", "same\n")
    write(dest / "tests/BUILD.bazel", 'cc_test(name = "t")\n')
    write(dest / "same.txt", "same\n")
    write(dest / "old/BUILD.bazel", OURS + "old\n")
    write(dest / "gen/parser.c", "/* @generated by bison */\n")
    write(dest / ".git/x", OURS)
    written, removed = ownership.sync(staging, dest)
    assert sorted(p.relative_to(dest).as_posix() for p in written) == ["BUILD.bazel", "lib/BUILD.bazel", "same.txt"]
    assert [p.relative_to(dest).as_posix() for p in removed] == ["old/BUILD.bazel"]
    assert not (dest / "old").exists()
    for kept in ("tests/BUILD.bazel", "gen/parser.c", ".git/x"):
        assert (dest / kept).is_file(), kept
    write(staging / "tests/BUILD.bazel", OURS + "generated tests\n")
    write(staging / "BUILD.bazel", OURS + "a = 2\n")
    with pytest.raises(ownership.Conflict) as caught:
        ownership.sync(staging, dest)
    assert caught.value.paths == ["tests/BUILD.bazel"]
    assert "Hand-written files are kept where they are" in str(caught.value)
    assert (dest / "BUILD.bazel").read_text() == OURS + "a = 1\n"
    # A regenerated file is replaced whatever stood there (MODULE.bazel, whose module()
    # entry the conversion read first).
    write(dest / "MODULE.bazel", 'module(name = "x")\n')
    write(staging / "MODULE.bazel", OURS + 'module(name = "x", version = "1")\n')
    del_tests = staging / "tests/BUILD.bazel"
    del_tests.unlink()
    ownership.sync(staging, dest, regenerated=("MODULE.bazel",))
    assert (dest / "MODULE.bazel").read_text() == OURS + 'module(name = "x", version = "1")\n'


def test_place(tmp_path: Path) -> None:
    target = tmp_path / "3rdparty/foo/BUILD.foo.bazel"
    ownership.place(target, OURS + "a = 1\n")
    ownership.place(target, OURS + "a = 2\n")
    assert target.read_text() == OURS + "a = 2\n"
    target.write_text("hand\n")
    ownership.place(target, "hand\n")  # identical: no conflict
    with pytest.raises(ownership.Conflict):
        ownership.place(target, OURS + "a = 3\n")
    assert target.read_text() == "hand\n"
